    {%- if ui_def(p['Disabled'], false) %} tabindex="-1"{%- endif %}
    {{ ui_attr_html(ui_def(p['Attrs'], {})) }}
  >{{ ui_def(children, '')|safe }}</a>
{%- else %}
  <button
    type="{{ ui_map_or(ui_def(p['Type'], ''), {'submit': 'submit', 'reset': 'reset'}, 'button') }}"
    class="{{ ui_compose('ui/button/button.variants.json', {'variant': ui_def(p['Variant'], ''), 'size': ui_def(p['Size'], ''), 'layout': ui_def(p['Layout'], '')}, [('pointer-events-none opacity-50' if ui_def(p['Disabled'], false) else ''), ui_def(p['Class'], '')]) }}"
    data-slot="button"
    {%- if ui_def(p['Disabled'], false) %} disabled{%- endif %}
    {%- if ui_is_set_str(ui_def(p['ID'], '')) %} id="{{ ui_def(p['ID'], '') }}"{%- endif %}
    {%- if ui_is_set_str(ui_def(p['Form'], '')) %} form="{{ ui_def(p['Form'], '') }}"{%- endif %}
    {%- if ui_is_set_str(ui_def(p['Role'], '')) %} role="{{ ui_def(p['Role'], '') }}"{%- endif %}
    {%- if ui_is_set_str(ui_def(p['TabIndex'], '')) %} tabindex="{{ ui_def(p['TabIndex'], '') }}"{%- endif %}
    {%- if ui_is_set_str(ui_def(p['AriaLabel'], '')) %} aria-label="{{ ui_def(p['AriaLabel'], '') }}"{%- endif %}
    {{ ui_attr_html(ui_def(p['Attrs'], {})) }}
  >{{ ui_def(children, '')|safe }}</button>
{%- endif %}

